    function Add-ToUserPath {
        param([string] $Directory)

        $userPath = [Environment]::GetEnvironmentVariable("Path", "User")
        if (-not (Test-PathContains -PathValue $userPath -Directory $Directory)) {
            if ([string]::IsNullOrWhiteSpace($userPath)) {
